questions.solution:
function exactlyOne(card, transfer, wallet) {
  let chosen = 0;
  if (card) chosen = chosen + 1;
  if (transfer) chosen = chosen + 1;
  if (wallet) chosen = chosen + 1;
  return chosen === 1;
}

console.log(exactlyOne(true, false, false));
console.log(exactlyOne(true, true, true));
console.log(exactlyOne(false, false, false));
console.log(exactlyOne(false, true, true));

